import{d as _,C as g,o as b,c as z,j as n,a as e,E as t,a3 as c}from"./chunks/framework.D4-ViStF.js";const f=JSON.parse('{"title":"庄子·养生主","description":"从缘督、庖丁到薪尽火传，理解庄子如何在有限生命中保全本真。","frontmatter":{"title":"庄子·养生主","description":"从缘督、庖丁到薪尽火传，理解庄子如何在有限生命中保全本真。","category":"guide","aliases":["养生主","庄子养生主","zhuangzi chapter 03"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-03.md","filePath":"daoism/zhuang-zi/chapter-03.md","lastUpdated":1788516578000}'),q={name:"daoism/zhuang-zi/chapter-03.md"},P=_({...q,setup(w){const d=[{id:"yuandu_s1",label:"吾生也有涯……殆而已矣",sentences:[[{text:"吾生也有涯",glossary:"sheng_youya"},"，而",{text:"知也无涯",glossary:"zhi_wuya"},"。"],["以有涯",{text:"随",glossary:"sui_zhuiqiu"},"无涯，",{text:"殆",glossary:"dai_weixian"},"已！"],[{text:"已而为知者",glossary:"yierweizhizhe"},"，",{text:"殆而已矣",glossary:"dai_eryi"},"。"]]},{id:"yuandu_s2",label:"为善无近名……可以尽年",sentences:[[{text:"为善无近名",glossary:"weishan_wujinming"},"，",{text:"为恶无近刑",glossary:"weie_wujinxing"},"，",{text:"缘督以为经",glossary:"yuandu_jing"},"，"],["可以",{text:"保身",glossary:"baoshen"},"，可以",{text:"全生",glossary:"quansheng"},"，可以",{text:"养亲",glossary:"yangqin"},"，可以",{text:"尽年",glossary:"jinnian"},"。"]]}],o=[{id:"sheng_youya",term:"吾生也有涯",pinyin:"wú shēng yě yǒu yá",meaning:"我的生命是有限的。涯：边际、界限；也：助词，表停顿；有涯：有边界、有限度。"},{id:"zhi_wuya",term:"知也无涯",pinyin:"zhī yě wú yá",meaning:"而知识是无限的。知：知识、认知；无涯：没有边界、无限。与「有涯」对举，构成有限与无限的根本矛盾。"},{id:"sui_zhuiqiu",term:"随",pinyin:"suí",meaning:"追随、跟随。以有涯随无涯：用有限的生命去追随无限的知识。随：此处含「穷追不舍」之意，非顺应之随。"},{id:"dai_weixian",term:"殆",pinyin:"dài",meaning:"危险、疲惫至极。【古今异义】非「大概/几乎」，此处为「危殆/危险」义。以有涯随无涯，殆已：用有限追无限，危险啊！"},{id:"yierweizhizhe",term:"已而为知者",pinyin:"yǐ ér wéi zhī zhě",meaning:"既然如此还要去追求知识的人。已：已经（知道危险）；而：却，转折；为知者：追求知识的人。"},{id:"dai_eryi",term:"殆而已矣",pinyin:"dài ér yǐ yǐ",meaning:"只有危险罢了。殆：危险；而已矣：罢了，表限定语气。与上句「殆已」呼应，语气更重。"},{id:"weishan_wujinming",term:"为善无近名",pinyin:"wéi shàn wú jìn míng",meaning:"做好事不要追求名声。为善：做好事；无：不要，否定祈使；近名：接近名誉、追求名声。⚠️ 非「不做好事」，而是「做好事但不执着于名」。"},{id:"weie_wujinxing",term:"为恶无近刑",pinyin:"wéi è wú jìn xíng",meaning:"做坏事不要触犯刑罚。为恶：做坏事；近刑：接近刑罚、触犯法律。⚠️ 非「不做坏事」，而是「即便做了也不要触犯刑罚」——庄子此处超越善恶道德判断，只言处世之道。与「为善无近名」对举，善恶两端皆不执着。"},{id:"yuandu_jing",term:"缘督以为经",pinyin:"yuán dū yǐ wéi jīng",meaning:"顺着自然中道作为常法。缘：顺着、依循；督：中脉、中道，人体督脉居中，引申为自然的中正之道；以为：用作；经：常法、准则。全句：顺应自然中道作为处世的根本原则。"},{id:"baoshen",term:"保身",pinyin:"bǎo shēn",meaning:"保全身体。保：保全、护持；身：形体。养生的第一层：形体不受损伤。"},{id:"quansheng",term:"全生",pinyin:"quán shēng",meaning:"保全生命的完整。全：完整、完全；生：生命。比「保身」更进一层：不仅形体无损，生命亦完整无缺。"},{id:"yangqin",term:"养亲",pinyin:"yǎng qīn",meaning:"奉养父母、尽孝道。亲：父母、亲人。能养亲，说明自身完好，有余力奉养他人。"},{id:"jinnian",term:"尽年",pinyin:"jìn nián",meaning:"享尽天年、活到自然寿命的终点。尽：穷尽、享尽；年：天年，自然寿命。四者递进：保身→全生→养亲→尽年，由己及人，由身及命。"}],y=[{id:"paoding_s1",label:"庖丁为文惠君解牛……乃中经首之会",sentences:[[{text:"庖丁",glossary:"paoding"},"为",{text:"文惠君",glossary:"wenhuijun"},{text:"解牛",glossary:"jieeniu"},"，"],[{text:"手之所触",glossary:"shou_chu"},"，",{text:"肩之所倚",glossary:"jian_yi"},"，",{text:"足之所履",glossary:"zu_lv"},"，",{text:"膝之所踦",glossary:"xi_yi"},"，"],[{text:"砉然向然",glossary:"hua_xiang"},"，",{text:"奏刀騞然",glossary:"zoudao_huo"},"，",{text:"莫不中音",glossary:"zhong_yin"},"。"],[{text:"合",glossary:"he_fuhe"},"于《",{text:"桑林",glossary:"sanglin"},"》之舞，",{text:"乃中",glossary:"nai_zhong"},"《",{text:"经首",glossary:"jingshou"},"》之",{text:"会",glossary:"hui_jiezou"},"。"]]},{id:"paoding_s2",label:"文惠君曰嘻善哉……技盖至此乎",sentences:[["文惠君曰：「嘻，善哉！",{text:"技",glossary:"ji_jishu"},{text:"盖",glossary:"gai_he"},"至此乎？」"]]},{id:"paoding_s3",label:"庖丁释刀对曰……进乎技矣",sentences:[["庖丁",{text:"释",glossary:"shi_fangxia"},"刀对曰：「臣之所好者，道也，",{text:"进乎技矣",glossary:"jin_ji"},"。"]]},{id:"paoding_s4",label:"始臣之解牛之时……因其固然",sentences:[["始臣之解牛之时，所见无非牛者。三年之后，",{text:"未尝",glossary:"weichang_quan"},"见全牛也。"],["方今之时，臣",{text:"以神遇",glossary:"yi_shenyv"},"而不",{text:"以目视",glossary:"yi_mushi"},"，",{text:"官知止",glossary:"guanzhi_zhi"},"而",{text:"神欲行",glossary:"shen_yuxing"},"。"],[{text:"依乎天理",glossary:"yi_tianli"},"，",{text:"批大郤",glossary:"pi_daxi"},"，",{text:"导大窾",glossary:"dao_dakuan"},"，",{text:"因其固然",glossary:"yin_guran"},"，"]]},{id:"paoding_s5",label:"技经肯綮之未尝……刀刃若新发于硎",sentences:[[{text:"技",glossary:"ji_zhijing"},{text:"经",glossary:"jing_jingmai"},{text:"肯綮之",glossary:"kenqing"},"未尝，而况",{text:"大軱",glossary:"dagu"},"乎！"],["良庖",{text:"岁",glossary:"sui_meinian"},"更刀，",{text:"割",glossary:"ge_qiege"},"也；",{text:"族庖",glossary:"zupao"},"月更刀，",{text:"折",glossary:"zhe_zheduan"},"也。"],["今臣之刀十九年矣，所解数千牛矣，而刀刃",{text:"若",glossary:"ruo_haoru"},{text:"新发于硎",glossary:"xin_faxing"},"。"]]},{id:"paoding_s6",label:"彼节者有间……是以十九年而刀刃若新发于硎",sentences:[[{text:"彼节者",glossary:"jiezhe_youjian"},"有",{text:"间",glossary:"jian_kongxi"},"，而刀刃者",{text:"无厚",glossary:"wu_hou"},"；"],["以",{text:"无厚",glossary:"wu_hou"},{text:"入",glossary:"ru_jinru"},"有间，",{text:"恢恢乎",glossary:"huihui_hu"},"其于",{text:"游刃必有余地",glossary:"youren_yudi"},"矣，"],["是以十九年而刀刃若新发于硎。"]]},{id:"paoding_s7",label:"虽然每至于族……善刀而藏之",sentences:[["虽然，",{text:"每至于族",glossary:"mei_zhi_zu"},"，吾见",{text:"其",glossary:"qi_nali"},{text:"难为",glossary:"nanwei_nan"},"，",{text:"怵然为戒",glossary:"chur_weijie"},"，"],[{text:"视为止",glossary:"shi_weizhi"},"，",{text:"行为迟",glossary:"xing_weichi"},"，动刀",{text:"甚微",glossary:"shen_wei"},"，"],[{text:"謋然",glossary:"huo_ran"},"已解，",{text:"如土委地",glossary:"tu_weidi"},"。"],["提刀而立，",{text:"为之",glossary:"weizhi_wei"},{text:"四顾",glossary:"sigu"},"，",{text:"为之",glossary:"weizhi_wei"},{text:"踌躇满志",glossary:"chouzhu_manzhi"},"，",{text:"善",glossary:"shan_cashi"},"刀而",{text:"藏之",glossary:"cangzhi"},"。」"]]},{id:"paoding_s8",label:"文惠君曰善哉……得养生焉",sentences:[["文惠君曰：「善哉！吾闻庖丁之言，",{text:"得",glossary:"de_lingwu"},{text:"养生",glossary:"yangsheng_dao"},"焉。」"]]}],m=[{id:"paoding",term:"庖丁",pinyin:"páo dīng",meaning:"厨师丁。庖：厨师；丁：名字。古人以职业加名为称。庄子寓言中的得道者，以解牛之技喻养生之道。"},{id:"wenhuijun",term:"文惠君",pinyin:"wén huì jūn",meaning:"梁惠王，战国时魏国君主。文惠：谥号；君：君主。"},{id:"jieeniu",term:"解牛",pinyin:"jiě niú",meaning:"宰牛、分解牛的肢体。解：分解、拆解。全篇以解牛喻顺道养生。"},{id:"shou_chu",term:"手之所触",pinyin:"shǒu zhī suǒ chù",meaning:"手所接触的地方。触：接触。四肢并用，描绘庖丁解牛时全身投入的状态。"},{id:"jian_yi",term:"肩之所倚",pinyin:"jiān zhī suǒ yǐ",meaning:"肩膀所倚靠的地方。倚：倚靠、支撑。"},{id:"zu_lv",term:"足之所履",pinyin:"zú zhī suǒ lǚ",meaning:"脚所踩踏的地方。履：踩踏、踏步。"},{id:"xi_yi",term:"膝之所踦",pinyin:"xī zhī suǒ yǐ",meaning:"膝盖所抵顶的地方。踦：单足支撑、膝盖抵顶。四句排比，手·肩·足·膝，全身协调运作。"},{id:"hua_xiang",term:"砉然向然",pinyin:"huā rán xiǎng rán",meaning:"皮骨分离的声音。砉：皮骨相离之声，读 huā；向：通「响」，声响。两个拟声叠词，描绘解牛时的声音节奏。【通假字】向通「响」。"},{id:"zoudao_huo",term:"奏刀騞然",pinyin:"zòu dāo huō rán",meaning:"进刀时发出騞然的声响。奏：进、运用；騞然：刀切入骨肉的响亮声音，读 huō。"},{id:"zhong_yin",term:"莫不中音",pinyin:"mò bù zhòng yīn",meaning:"无不合乎音律节奏。中：符合，读 zhòng；音：音律、节拍。⚠️ 中读 zhòng（符合），非 zhōng（中间）。"},{id:"he_fuhe",term:"合",pinyin:"hé",meaning:"符合、契合。合于《桑林》之舞：与《桑林》乐舞的节奏相契合。"},{id:"sanglin",term:"桑林",pinyin:"sāng lín",meaning:"商汤时代的乐舞名。桑林：传说为商汤祭祀时所用的乐舞，节奏舒缓庄重。"},{id:"nai_zhong",term:"乃中",pinyin:"nǎi zhòng",meaning:"又符合。乃：又、而且；中：符合，读 zhòng。"},{id:"jingshou",term:"经首",pinyin:"jīng shǒu",meaning:"尧时乐曲名。经首：传说为尧时《咸池》乐章的篇名，节奏和谐。"},{id:"hui_jiezou",term:"会",pinyin:"huì",meaning:"节奏、节拍。【古今异义】非「会议/相会」，此处指乐曲的节拍节奏。"},{id:"ji_jishu",term:"技",pinyin:"jì",meaning:"技艺、技术。文惠君以「技」问，庖丁以「道」答，形成技与道的对比。"},{id:"gai_he",term:"盖",pinyin:"hé",meaning:"怎么、何。通「盍」，疑问副词。【通假字】⚠️ 读 hé，非「盖子/大概」义。技盖至此乎：技艺怎么能达到这种程度？"},{id:"shi_fangxia",term:"释",pinyin:"shì",meaning:"放下、放置。释刀：放下刀。【古今异义】非「解释」，此处为「放下」义。"},{id:"jin_ji",term:"进乎技矣",pinyin:"jìn hū jì yǐ",meaning:"超越了技艺（的层次）。进：超越、高于；乎：介词，于、比；技：技艺。臣之所好者道也，进乎技矣：我所追求的是道，已经超越了技艺的层次。"},{id:"weichang_quan",term:"未尝",pinyin:"wèi cháng",meaning:"不曾、从未。三年之后，未尝见全牛：三年后，不曾再看到完整的牛（眼中只有结构与空隙）。"},{id:"yi_shenyv",term:"以神遇",pinyin:"yǐ shén yù",meaning:"用心神感应接触。神：精神、心神；遇：接触、感应。不用眼睛看，而用心神感知牛的内在结构。"},{id:"yi_mushi",term:"以目视",pinyin:"yǐ mù shì",meaning:"用眼睛看。与「以神遇」对举：目视是感官层面，神遇是精神层面。"},{id:"guanzhi_zhi",term:"官知止",pinyin:"guān zhī zhǐ",meaning:"感官的认知停止运作。官：感官（眼耳鼻等）；知：认知；止：停止。感官退位，精神主导。"},{id:"shen_yuxing",term:"神欲行",pinyin:"shén yù xíng",meaning:"心神自然运行。神：心神、精神；欲：自然地、顺势地；行：运行。官知止而神欲行：感官停止，心神自然流动——即「无为而为」的状态。"},{id:"yi_tianli",term:"依乎天理",pinyin:"yī hū tiān lǐ",meaning:"依循牛体自然的纹理结构。天理：天然的纹理，指牛体骨骼肌肉的自然结构；非「天道伦理」。依乎：依照、顺着。"},{id:"pi_daxi",term:"批大郤",pinyin:"pī dà xì",meaning:"劈入大的骨骼缝隙。批：劈、击；郤：通「隙」，缝隙、空隙。【通假字】郤通「隙」。"},{id:"dao_dakuan",term:"导大窾",pinyin:"dǎo dà kuǎn",meaning:"引刀进入大的空腔。导：引导、顺势而入；窾：空腔、空穴处。"},{id:"yin_guran",term:"因其固然",pinyin:"yīn qí gù rán",meaning:"顺着牛体本来的自然结构。因：顺着、依循；固然：本来如此、天然的样子。三句并列：依天理→批大郤→导大窾→因固然，层层描绘顺道而为。"},{id:"ji_zhijing",term:"技",pinyin:"jī",meaning:"枝节、细小的筋络。【古今异义】此处读 jī，非「技艺」，指细小的筋脉枝节。"},{id:"jing_jingmai",term:"经",pinyin:"jīng",meaning:"经脉、大筋。经：纵向的大筋脉。技经：细小筋络与大筋脉。"},{id:"kenqing",term:"肯綮之",pinyin:"kěn qìng zhī",meaning:"筋骨结合的关键处。肯：附着在骨上的肉；綮：筋骨交结处；之：助词。技经肯綮之未尝：连细筋大脉、筋骨交结处都不曾碰触。"},{id:"dagu",term:"大軱",pinyin:"dà gū",meaning:"大骨头。軱：粗大的骨骼。而况大軱乎：更何况大骨头（当然不会去硬砍）。"},{id:"sui_meinian",term:"岁",pinyin:"suì",meaning:"每年、一年。名词作状语。良庖岁更刀：好厨师每年换一把刀。"},{id:"ge_qiege",term:"割",pinyin:"gē",meaning:"割切、横向切割。良庖岁更刀，割也：好厨师每年换刀，因为是割（切肉）。"},{id:"zupao",term:"族庖",pinyin:"zú páo",meaning:"普通厨师、一般的厨师。族：众、一般；庖：厨师。与「良庖」对举。"},{id:"zhe_zheduan",term:"折",pinyin:"zhé",meaning:"砍断、折断。族庖月更刀，折也：普通厨师每月换刀，因为是砍（骨头），刀易折损。割·折对举：良庖顺纹理割肉，族庖硬砍骨头。"},{id:"ruo_haoru",term:"若",pinyin:"ruò",meaning:"好像、如同。若新发于硎：好像刚从磨刀石上磨出来一样。"},{id:"xin_faxing",term:"新发于硎",pinyin:"xīn fā yú xíng",meaning:"刚从磨刀石上磨出来（的新刀）。发：出、磨出；硎：磨刀石。形容刀刃锋利如新。"},{id:"jiezhe_youjian",term:"彼节者",pinyin:"bǐ jié zhě",meaning:"那牛的骨节之间。节：骨节；者：助词。"},{id:"jian_kongxi",term:"间",pinyin:"jiàn",meaning:"空隙、间隙。⚠️ 读 jiàn，非 jiān。彼节者有间：骨节之间有空隙。"},{id:"wu_hou",term:"无厚",pinyin:"wú hòu",meaning:"没有厚度（极薄）。刀刃者无厚：刀刃薄到几乎没有厚度。以无厚入有间：用极薄的刀刃进入有空隙的骨节间。"},{id:"ru_jinru",term:"入",pinyin:"rù",meaning:"进入。以无厚入有间：以极薄之刃进入骨节空隙之中。"},{id:"huihui_hu",term:"恢恢乎",pinyin:"huī huī hū",meaning:"宽绰有余的样子。恢恢：宽广、宽裕；乎：形容词词尾。"},{id:"youren_yudi",term:"游刃必有余地",pinyin:"yóu rèn bì yǒu yú dì",meaning:"刀刃游走必然有宽裕的空间。游刃：刀刃自由游走；余地：多余的空间。成语「游刃有余」出处。"},{id:"mei_zhi_zu",term:"每至于族",pinyin:"měi zhì yú zú",meaning:"每当遇到筋骨交错聚结的地方。族：聚结、丛聚，指筋骨交错复杂处。【古今异义】非「族群」，此处为「聚结」义。"},{id:"qi_nali",term:"其",pinyin:"qí",meaning:"那里、那处。代词，指筋骨交错聚结之处。"},{id:"nanwei_nan",term:"难为",pinyin:"nán wéi",meaning:"难以处理、难以下刀。难：困难；为：处理、应对。【古今异义】非「为难他人」，此处为「难以处置」。"},{id:"chur_weijie",term:"怵然为戒",pinyin:"chù rán wéi jiè",meaning:"警惕戒慎的样子。怵然：警惕、小心谨慎的样子；为戒：保持警戒。"},{id:"shi_weizhi",term:"视为止",pinyin:"shì wéi zhǐ",meaning:"目光因此凝聚停止（专注于一处）。视：目光；为：因此；止：停止游移，专注凝视。"},{id:"xing_weichi",term:"行为迟",pinyin:"xíng wéi chí",meaning:"动作因此放缓。行：动作；为：因此；迟：缓慢。视为止·行为迟：目光凝聚，动作放缓，高度专注。"},{id:"shen_wei",term:"甚微",pinyin:"shèn wēi",meaning:"极其轻微。甚：极、非常；微：轻微、细小。动刀甚微：用刀极其轻微，不强行硬切。"},{id:"huo_ran",term:"謋然",pinyin:"huò rán",meaning:"骨肉分离的声音。謋：骨肉剥离时发出的声响，读 huò。謋然已解：一声謋然，牛已分解完毕。"},{id:"tu_weidi",term:"如土委地",pinyin:"rú tǔ wěi dì",meaning:"像泥土一样散落在地上。委：散落、堆积；地：地面。形容牛体自然分解、轻松落地，毫不费力。"},{id:"weizhi_wei",term:"为之",pinyin:"wèi zhī",meaning:"因此、为此。介词结构，表示因为解牛这件事而产生的动作。"},{id:"sigu",term:"四顾",pinyin:"sì gù",meaning:"向四周环顾。四：四方；顾：回头看、环顾。提刀而立，为之四顾：提着刀站立，环顾四周（欣赏自己的工作）。"},{id:"chouzhu_manzhi",term:"踌躇满志",pinyin:"chóu chú mǎn zhì",meaning:"从容自得、志得意满。踌躇：从容自得的样子；满志：心满意足。成语「踌躇满志」出处。⚠️ 此处非「犹豫不决」，而是「从容自得」义。"},{id:"shan_cashi",term:"善",pinyin:"shàn",meaning:"擦拭、拭净。【古今异义】此处非「善良/好」，而是动词「擦拭」。善刀：擦净刀刃。"},{id:"cangzhi",term:"藏之",pinyin:"cáng zhī",meaning:"将它收藏起来。藏：收藏、收好；之：代词，指刀。善刀而藏之：擦净刀后收好，动作从容，首尾呼应「释刀」。"},{id:"de_lingwu",term:"得",pinyin:"dé",meaning:"领悟、获得。得养生焉：从中领悟了养生的道理。"},{id:"yangsheng_dao",term:"养生",pinyin:"yǎng shēng",meaning:"养护生命的道理。养：养护；生：生命。文惠君以庖丁解牛之道悟出养生之理：顺应自然结构，避开硬碰硬，游刃有余——即《养生主》的核心旨意。"}],l=[{id:"youshi_s1",label:"公文轩见右师而惊曰……其人与",sentences:[[{text:"公文轩",glossary:"gongwenxuan"},"见",{text:"右师",glossary:"youshi"},"而惊曰：「是何人也？",{text:"恶乎介也",glossary:"ewuhu_jie"},"？"],[{text:"天与",glossary:"tian_yu"},"，",{text:"其人与",glossary:"qi_ren_yu"},"？」"]]},{id:"youshi_s2",label:"曰天也非人也……非人也",sentences:[["曰：「",{text:"天也",glossary:"tian_ye"},"，非人也。"],[{text:"天之生",glossary:"tian_zhisheng"},{text:"是",glossary:"shi_ci"},{text:"使",glossary:"shi_shi"},{text:"独也",glossary:"du_ye"},"，"],[{text:"人之貌",glossary:"ren_mao"},{text:"有与也",glossary:"you_yu_ye"},"。"],[{text:"以",glossary:"yi_yinci"},{text:"是",glossary:"shi_ci2"},{text:"知",glossary:"zhi_panduan"},{text:"其",glossary:"qi_ta2"},{text:"天也",glossary:"tian_ye"},"，非人也。」"]]},{id:"zezhi_s1",label:"泽雉十步一啄……不善也",sentences:[[{text:"泽雉",glossary:"zezhi"},"十步一啄，百步一饮，不",{text:"蕲",glossary:"qi_qiqiu"},{text:"畜乎樊中",glossary:"xu_fanzhong"},"。"],[{text:"神虽王",glossary:"shen_wang"},"，",{text:"不善也",glossary:"bu_shan"},"。"]]}],h=[{id:"gongwenxuan",term:"公文轩",pinyin:"gōng wén xuān",meaning:"人名，庄子寓言中的人物。公文：复姓；轩：名。见右师而惊，引出对「天命」与「人为」的追问。"},{id:"youshi",term:"右师",pinyin:"yòu shī",meaning:"官职名，此处指担任右师之职的人。右师：宋国官职；此人只有一只脚（独足），公文轩见而惊异。"},{id:"ewuhu_jie",term:"恶乎介也",pinyin:"wū hū jiè yě",meaning:"怎么（只有）一只脚呢？恶乎：怎么、为何，疑问副词；介：单、独，此处指独足、只有一只脚。【古今异义】介非「介绍/介入」，此处为「单独、孤单」义，引申为缺一足。"},{id:"tian_yu",term:"天与",pinyin:"tiān yú",meaning:"是天（造成）的吗？天：自然、天命；与：语气词，表疑问，通「欤」。【通假字】与通「欤」，读 yú。"},{id:"qi_ren_yu",term:"其人与",pinyin:"qí rén yú",meaning:"还是人（造成）的呢？其：还是，表选择的连词；人：人为、人的行为；与：疑问语气词，通「欤」。天与·其人与：是天生如此，还是人为所致？"},{id:"tian_ye",term:"天也",pinyin:"tiān yě",meaning:"是天（造成）的。天：自然天命；也：判断语气词。两处「天也，非人也」首尾呼应，强调断语。"},{id:"tian_zhisheng",term:"天之生",pinyin:"tiān zhī shēng",meaning:"天（自然）生成他。天：自然；之：助词，取消句子独立性；生：生成、造就。"},{id:"shi_ci",term:"是",pinyin:"shì",meaning:"他、这个人。指示代词，指右师。天之生是：天生成他（右师）。"},{id:"shi_shi",term:"使",pinyin:"shǐ",meaning:"使得、让。使独也：使他独足。"},{id:"du_ye",term:"独也",pinyin:"dú yě",meaning:"只有一只脚。独：单独、孤单，此处指独足。天之生是使独也：天生就让他只有一只脚。"},{id:"ren_mao",term:"人之貌",pinyin:"rén zhī mào",meaning:"人的外貌形态。貌：外貌、形态。"},{id:"you_yu_ye",term:"有与也",pinyin:"yǒu yǔ yě",meaning:"是（天）赋予的。与：给予、赋予；也：语气词。人之貌有与也：人的外貌形态都是天所赋予的。与上句「天之生是使独也」互文——无论独足还是双足，皆天所为，非人力所致。"},{id:"yi_yinci",term:"以",pinyin:"yǐ",meaning:"因此、凭此。介词，表凭借或原因。以是知其天也：凭此知道那是天（造成）的。"},{id:"shi_ci2",term:"是",pinyin:"shì",meaning:"这、此。指示代词，指上文「天之生是使独也，人之貌有与也」这个道理。"},{id:"zhi_panduan",term:"知",pinyin:"zhī",meaning:"知道、判断。以是知其天也：凭此判断那是天（的安排）。"},{id:"qi_ta2",term:"其",pinyin:"qí",meaning:"那（是）、它（是）。代词，指右师独足这件事。"},{id:"zezhi",term:"泽雉",pinyin:"zé zhì",meaning:"沼泽中的野鸡。泽：沼泽、湿地；雉：野鸡。泽雉自由觅食于旷野，是本段「顺性自然」的核心意象。"},{id:"qi_qiqiu",term:"蕲",pinyin:"qí",meaning:"祈求、希望。通「祈」。【通假字】蕲通「祈」，读 qí。不蕲：不祈求、不希望。"},{id:"xu_fanzhong",term:"畜乎樊中",pinyin:"xù hū fán zhōng",meaning:"被豢养在笼子里。畜：豢养、圈养；乎：于，介词；樊：笼子、栅栏；中：里面。不蕲畜乎樊中：不祈求被关在笼中豢养。泽雉宁可旷野艰辛觅食，不愿笼中坐享安逸——喻顺自然之性，不以外物束缚本性。"},{id:"shen_wang",term:"神虽王",pinyin:"shén suī wàng",meaning:"精神虽然旺盛。神：精神；虽：虽然；王：通「旺」，旺盛、充盛，读 wàng。【通假字】王通「旺」。笼中食物充足，精神看似饱满——但这是虚假的充盛。"},{id:"bu_shan",term:"不善也",pinyin:"bù shàn yě",meaning:"（却）不好啊。善：好、妥善；也：感叹语气词。神虽王，不善也：精神虽旺盛，却不好——因为失去了自由与本性。呼应右师一足：形体残缺是天命，无可厚非；精神被囚才是真正的不善。"}],u=[{id:"qinshi_s1",label:"老聃死秦失吊之……可乎",sentences:[["老聃死，",{text:"秦失",glossary:"qinshi"},{text:"吊之",glossary:"diao_zhi"},"，",{text:"三号而出",glossary:"san_hao"},"。"],["弟子曰：「",{text:"非",glossary:"fei_bushi"},"夫子之友邪？」"],["曰：「",{text:"然",glossary:"ran_shi"},"。」"],["「然则",{text:"吊焉若此",glossary:"diao_ruoci"},"，",{text:"可乎",glossary:"ke_hu"},"？」"]]},{id:"qinshi_s2",label:"曰然始也吾以为其人也……不蕲哭而哭者",sentences:[["曰：「然。始也",{text:"吾以为其人也",glossary:"wu_yiwei_qiren"},"，而今非也。"],[{text:"向",glossary:"xiang_gangcai"},"吾入而吊焉，有老者哭之，如哭其子；少者哭之，如哭其母。"],[{text:"彼",glossary:"bi_tamen"},{text:"其",glossary:"qi_zhi"},{text:"所以",glossary:"suoyi_yuanyin"},{text:"会之",glossary:"hui_zhi"},"，必有",{text:"不蕲言而言",glossary:"buqi_yan"},"，",{text:"不蕲哭而哭者",glossary:"buqi_ku"},"。"]]},{id:"qinshi_s3",label:"是遁天倍情……遁天之刑",sentences:[["是",{text:"遁天倍情",glossary:"duntian_beiqing"},"，",{text:"忘其所受",glossary:"wang_suoshou"},"，古者谓之",{text:"遁天之刑",glossary:"duntian_zhixing"},"。"]]},{id:"qinshi_s4",label:"适来夫子时也……帝之县解",sentences:[[{text:"适来",glossary:"shi_lai"},"，夫子",{text:"时也",glossary:"shi_ye"},"；",{text:"适去",glossary:"shi_qu"},"，夫子",{text:"顺也",glossary:"shun_ye"},"。"],[{text:"安时而处顺",glossary:"anshi_chushun"},"，",{text:"哀乐不能入也",glossary:"aile_buru"},"，古者谓之",{text:"帝之县解",glossary:"di_xuanjie"},"。」"]]},{id:"huochuan_s1",label:"指穷于为薪……不知其尽也",sentences:[[{text:"指穷于为薪",glossary:"zhi_qiong_xin"},"，",{text:"火传也",glossary:"huo_chuan"},"，",{text:"不知其尽也",glossary:"buzhi_qijin"},"。"]]}],p=[{id:"qinshi",term:"秦失",pinyin:"qín shī",meaning:"人名，老聃的朋友。失：读 yì，一说读 shī。庄子寓言中体现「安时处顺」的得道者。"},{id:"diao_zhi",term:"吊之",pinyin:"diào zhī",meaning:"前去吊唁他（老聃）。吊：吊唁、悼念死者；之：代词，指老聃。"},{id:"san_hao",term:"三号而出",pinyin:"sān háo ér chū",meaning:"哭号三声就出来了。三：表示次数少，非确指；号：放声哭泣，读 háo；而出：就出来了。与弟子们的痛哭形成强烈对比。"},{id:"fei_bushi",term:"非",pinyin:"fēi",meaning:"不是。非夫子之友邪：他不是您的朋友吗？用反问确认秦失与老聃的友谊，以引出下文的质疑。"},{id:"ran_shi",term:"然",pinyin:"rán",meaning:"是的、对。应答词，表肯定。【古今异义】非「然而/这样」，此处为应答「是」。"},{id:"diao_ruoci",term:"吊焉若此",pinyin:"diào yān ruò cǐ",meaning:"吊唁（却）如此（简短）。焉：语气助词；若此：像这样，指仅三号而出。"},{id:"ke_hu",term:"可乎",pinyin:"kě hū",meaning:"可以吗？合适吗？表示质疑秦失吊唁方式是否得体。"},{id:"wu_yiwei_qiren",term:"吾以为其人也",pinyin:"wú yǐ wéi qí rén yě",meaning:"我以为他（老聃）是超凡脱俗之人。其人：那样的人，指真正得道之人；以为：认为。而今非也：而现在（看来）不是了——因为他的弟子们哭得如此悲痛，说明老聃并未真正教导弟子超越生死。"},{id:"xiang_gangcai",term:"向",pinyin:"xiàng",meaning:"刚才、方才。【古今异义】非「方向」，此处为时间副词「刚才」。向吾入而吊焉：刚才我进去吊唁的时候。"},{id:"bi_tamen",term:"彼",pinyin:"bǐ",meaning:"那些人、他们。指示代词，指在场哭泣的老者和少者。"},{id:"qi_zhi",term:"其",pinyin:"qí",meaning:"他们的、那些人的。第三人称代词，指彼（那些哭泣者）。"},{id:"suoyi_yuanyin",term:"所以",pinyin:"suǒ yǐ",meaning:"……的原因。【古今异义】非现代「所以（因此）」，此处为「……的原因/缘故」，名词性结构。"},{id:"hui_zhi",term:"会之",pinyin:"huì zhī",meaning:"聚集到这里（来吊唁）。会：聚集、汇聚；之：到这里。彼其所以会之：他们之所以聚集来此（吊唁）。"},{id:"buqi_yan",term:"不蕲言而言",pinyin:"bù qí yán ér yán",meaning:"不想说话却（情不自禁地）说了。蕲：通「祈」，祈求、希望；不蕲言：不想开口。【通假字】蕲通「祈」。指哭泣者被情绪驱使，失去自制。"},{id:"buqi_ku",term:"不蕲哭而哭者",pinyin:"bù qí kū ér kū zhě",meaning:"不想哭泣却（情不自禁地）哭了的人。与「不蕲言而言」对举，形容弟子们被悲情所控制，违背自然。"},{id:"duntian_beiqing",term:"遁天倍情",pinyin:"dùn tiān bèi qíng",meaning:"逃避天命、违背真情。遁天：逃避、背离自然天命；倍情：违背真实情感；倍通「背」。【通假字】倍通「背」，读 bèi。死生有命，悲痛过度即是逃避天命、违背自然之情。"},{id:"wang_suoshou",term:"忘其所受",pinyin:"wàng qí suǒ shòu",meaning:"忘记了自己所受（于天）的本性。所受：所受于天的自然本性，即生死自然之理。忘其所受：忘记了生命本是天所赋予、死亦是天命归还。"},{id:"duntian_zhixing",term:"遁天之刑",pinyin:"dùn tiān zhī xíng",meaning:"逃避天命所受的刑罚。遁天：背离自然天命；刑：刑罚、惩罚。古者谓之遁天之刑：古人称这种（过度悲哀）为逃避天命的刑罚——自我折磨即是受刑。"},{id:"shi_lai",term:"适来",pinyin:"shì lái",meaning:"恰好来到（这个世界）。适：恰好、适逢；来：来到，指出生。"},{id:"shi_ye",term:"时也",pinyin:"shí yě",meaning:"是顺应时机（的结果）。时：时机、时运；也：判断语气词。适来，夫子时也：先生恰好来到，是顺应时机。"},{id:"shi_qu",term:"适去",pinyin:"shì qù",meaning:"恰好离去（这个世界）。适：恰好；去：离去，指死亡。与「适来」对举，来与去皆「适」——皆是自然而然。"},{id:"shun_ye",term:"顺也",pinyin:"shùn yě",meaning:"是顺应自然（的结果）。顺：顺应自然规律；也：判断语气词。适去，夫子顺也：先生恰好离去，是顺应自然。时·顺对举：来是时，去是顺，生死皆自然。"},{id:"anshi_chushun",term:"安时而处顺",pinyin:"ān shí ér chǔ shùn",meaning:"安于时机而处于顺应之中。安时：安然接受时机（生死的时节）；处顺：处于顺应自然的状态。呼应第一段「缘督以为经」，是养生的核心态度。"},{id:"aile_buru",term:"哀乐不能入也",pinyin:"āi lè bù néng rù yě",meaning:"悲哀与喜乐都不能侵入（内心）。哀乐：悲哀与喜乐，代指一切情绪波动；入：侵入、扰动。安时处顺则哀乐不入，与《齐物论》「喜怒哀乐，其未发」相通。"},{id:"di_xuanjie",term:"帝之县解",pinyin:"dì zhī xuán jiě",meaning:"天帝（自然）给予的悬解之法。帝：天帝，指自然造化；县：通「悬」，悬挂；解：解脱、解开。【通假字】县通「悬」。县解：悬挂着解开——如倒悬之人被解救，喻从生死哀乐的束缚中彻底解脱。古者谓之帝之县解：古人称这种境界为天帝赐予的解脱。"},{id:"zhi_qiong_xin",term:"指穷于为薪",pinyin:"zhǐ qióng yú wéi xīn",meaning:"手指（的脂油）在引火为薪时耗尽了。指：手指，一说「脂」，油脂；穷：耗尽；为薪：作为柴薪、引火之用。喻形体（薪）终将耗尽。【一说】指通「脂」，脂油耗尽于燃薪之中。"},{id:"huo_chuan",term:"火传也",pinyin:"huǒ chuán yě",meaning:"火焰（却）传续下去了。火：火焰，喻精神、生命之本；传：传递、延续。薪尽而火传：形体消亡而精神延续，喻生命的本质不随形体消逝。"},{id:"buzhi_qijin",term:"不知其尽也",pinyin:"bù zhī qí jìn yě",meaning:"不知道它（何时）终尽。其：它，指火；尽：终尽、熄灭。火传而不知其尽：精神生命延续不绝，无从知晓其终点。全句是《养生主》的终极意象：形体如薪，终将耗尽；精神如火，传续不息。"}];return(j,i)=>{const x=g("DaoReadingPrelude"),a=g("DaoTextReading"),s=g("DaoKeywordCards"),r=g("DaoLineGuide");return b(),z("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·养生主",tabindex:"-1"},[e("庄子·养生主 "),n("a",{class:"header-anchor",href:"#庄子·养生主","aria-label":'Permalink to "庄子·养生主"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"「养生主」中的「养生」，不是今天常说的保健或延寿。")]),n("p",null,"它问的是：生命有限、外物纷杂，一个人怎样不被名利、技艺、恐惧与哀乐过度损耗，仍能保全生命本来的节律？「主」可理解为要旨、关键；本篇要谈的，正是养护生命的根本方法。"),n("p",null,"庄子没有直接给出一套养生术，而是让庖丁、右师、泽雉和秦失依次出现：从顺着事物的结构做事，到分清天命与人为，再到面对自由和生死。")],-1)),t(x,{title:"从庖丁解牛，看庄子如何说养生",summary:"养生主是《庄子》内篇中很短却极为凝练的一篇。它把养生从身体保养推向更根本的问题：怎样在有限的生命里，顺着事物本有的纹理行动，而不把自己耗在硬碰硬的对抗中。",points:[{label:"先看",text:"顺着总纲、庖丁、右师、泽雉与秦失几个模块，辨认每一次问题的转换。"},{label:"再问",text:"「以无厚入有间」为什么既是解牛的方法，也是处理复杂处境的比喻？"},{label:"最后",text:"「安时而处顺」是在逃避现实，还是在不被现实完全拖住？"}],hint:"篇幅虽短，建议分模块读。每读完一段，先回到原文，再停在引读卡提出的问题上。"}),i[3]||(i[3]=n("h2",{id:"一、总纲·缘督以为经",tabindex:"-1"},[e("一、总纲·缘督以为经 "),n("a",{class:"header-anchor",href:"#一、总纲·缘督以为经","aria-label":'Permalink to "一、总纲·缘督以为经"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:d,glossary:o,"default-mode":"classic","aria-label":"养生主·总纲 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"有涯",pinyin:["yǒu","yá"],meaning:"有边界、有限度。涯：边际、尽头。"},{term:"无涯",pinyin:["wú","yá"],meaning:"无边无际、没有尽头。"},{term:"殆",pinyin:["dài"],meaning:"危险、疲惫至极。以有涯随无涯，殆已：用有限的生命追逐无限的知识，危险啊！"},{term:"已而为知者",pinyin:["yǐ","ér","wéi","zhī","zhě"],meaning:"明知如此还要去追求。已：已经知道危险；知通「智」，求知。"},{term:"殆而已矣",pinyin:["dài","ér","yǐ","yǐ"],meaning:"不过是自取危险罢了。"},{term:"为善无近名",pinyin:["wéi","shàn","wú","jìn","míng"],meaning:"做好事不要为了追求名声。近：靠近、追求。"},{term:"为恶无近刑",pinyin:["wéi","è","wú","jìn","xíng"],meaning:"做坏事不要触犯刑罚的边界。近刑：接近刑罚。"},{term:"缘督以为经",pinyin:["yuán","dū","yǐ","wéi","jīng"],meaning:"顺着自然的中道作为处世的常法。缘：顺着；督：人体正中的督脉，引申为自然中道；经：常法、准则。"},{term:"保身",pinyin:["bǎo","shēn"],meaning:"保全身体，不受外物损伤。"},{term:"全生",pinyin:["quán","shēng"],meaning:"保全生命的完整与本真。"},{term:"养亲",pinyin:["yǎng","qīn"],meaning:"奉养父母亲人。"},{term:"尽年",pinyin:["jìn","nián"],meaning:"活尽天年，享尽自然赋予的寿命。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"用有限追无限，结果只有一个——耗尽",subtitle:"知识是工具，不是终点。把工具当终点，是现代人最普遍的疲惫来源。",lines:[{text:"吾生也有涯，而知也无涯。以有涯随无涯，殆已！",tone:"困境",guide:"全篇开门见山，庄子用一个极简的对比，点出人类最根本的困境：生命有边界，知识无边界。用有限追无限，结果只有一个——耗尽。这不是在说「不要学习」，而是在说：当你把「知」当作目的本身，用生命去填那个无底洞，你就已经输了。知识是工具，不是终点。"},{text:"已而为知者，殆而已矣。",tone:"执迷",guide:"更深一层：明知这样做很危险，还要继续——这不是勇气，是执迷。庄子的语气里有一丝悲悯：不是不懂，是停不下来。这句话两千年后读来，依然刺耳。"},{text:"为善无近名，为恶无近刑。",tone:"内尺",guide:"这两句常被误读。庄子不是在说「做好事别出名、做坏事别被抓」——他是在说：不要用「名」和「刑」作为行为的边界。做好事，不是为了名声——一旦为名而善，善就变质了；做坏事，不是因为有刑才不做——一旦只是怕刑，恶心未除。真正的行为准则，不在名与刑的外部约束，而在「缘督」的内在自然。"},{text:"缘督以为经，可以保身，可以全生，可以养亲，可以尽年。",tone:"总纲",guide:"全篇的核心纲领，四个「可以」层层递进：保身（身体不受外物损伤）→ 全生（生命的本真得以完整保全）→ 养亲（有余力奉养亲人）→ 尽年（活尽天赋的自然寿命）。「缘督」是方法，四个「可以」是结果。督脉是人体正中的经脉，不偏不倚——「缘督以为经」，就是顺着那条自然的中道走，不强行，不执着，不被名利是非拉偏。"}]}),i[7]||(i[7]=n("h2",{id:"二、庖丁解牛",tabindex:"-1"},[e("二、庖丁解牛 "),n("a",{class:"header-anchor",href:"#二、庖丁解牛","aria-label":'Permalink to "二、庖丁解牛"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:y,glossary:m,"default-mode":"classic","aria-label":"养生主·庖丁解牛 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"庖丁",pinyin:["páo","dīng"],meaning:"厨师。庖：厨房，引申为厨师；丁：人名。"},{term:"文惠君",pinyin:["wén","huì","jūn"],meaning:"梁惠王，战国时魏国君主。"},{term:"踦",pinyin:["yǐ"],meaning:"单腿支撑、抵住。膝之所踦：用膝盖抵住牛体。"},{term:"砉然",pinyin:["huā","rán"],meaning:"皮肉分离的声音。砉：象声词，皮骨相离之声。"},{term:"奏刀",pinyin:["zòu","dāo"],meaning:"进刀、运刀。奏：进、施展。"},{term:"騞然",pinyin:["huō","rán"],meaning:"刀切入的声音，响亮清脆。"},{term:"莫不中音",pinyin:["mò","bù","zhòng","yīn"],meaning:"无不合乎节拍。中：符合；音：音乐节拍。"},{term:"桑林",pinyin:["sāng","lín"],meaning:"商汤时代的乐舞名。合于《桑林》之舞：动作合乎桑林乐舞的节奏。"},{term:"经首",pinyin:["jīng","shǒu"],meaning:"尧时代的乐曲名。乃中《经首》之会：节奏符合经首乐曲的韵律。"},{term:"释刀",pinyin:["shì","dāo"],meaning:"放下刀。"},{term:"进乎技矣",pinyin:["jìn","hū","jì","yǐ"],meaning:"超越了技艺的层面，进入了道的境界。进：超越、超过。"},{term:"天理",pinyin:["tiān","lǐ"],meaning:"牛体自然的骨骼肌理结构，非道德之「天理」。"},{term:"批大郤",pinyin:["pī","dà","xì"],meaning:"劈入大的骨骼缝隙处。批：劈、击；郤通「隙」，缝隙。"},{term:"导大窾",pinyin:["dǎo","dà","kuǎn"],meaning:"引刀进入大的空腔处。导：引导；窾：空腔、空洞。"},{term:"因其固然",pinyin:["yīn","qí","gù","rán"],meaning:"顺着牛体本来的自然结构。因：顺着；固然：本来如此的样子。"},{term:"技经肯綮",pinyin:["jī","jīng","kěn","qìng"],meaning:"筋骨交错聚结的地方。技经：细小的经络筋脉；肯：附在骨上的肉；綮：筋骨结合处。"},{term:"大軱",pinyin:["dà","gū"],meaning:"大骨头。軱：大骨。技经肯綮之未尝，而况大軱：连筋骨交错处都不碰，何况大骨头。"},{term:"良庖岁更刀",pinyin:["liáng","páo","suì","gēng","dāo"],meaning:"好厨师一年换一把刀。因为用割的方式，刀刃损耗慢。"},{term:"族庖月更刀",pinyin:["zú","páo","yuè","gēng","dāo"],meaning:"普通厨师一个月换一把刀。族：众、普通；因为用砍的方式，刀刃损耗快。"},{term:"新发于硎",pinyin:["xīn","fā","yú","xíng"],meaning:"刚从磨刀石上磨出来一样锋利。硎：磨刀石。"},{term:"节者有间",pinyin:["jié","zhě","yǒu","jiān"],meaning:"骨节之间有缝隙。间：空隙、间隔。"},{term:"刀刃者无厚",pinyin:["dāo","rèn","zhě","wú","hòu"],meaning:"刀刃极薄，几乎没有厚度。"},{term:"恢恢乎",pinyin:["huī","huī","hū"],meaning:"宽绰有余的样子。恢恢：宽广、宽裕。"},{term:"族",pinyin:["zú"],meaning:"筋骨交错聚结之处，难以下刀的地方。"},{term:"怵然为戒",pinyin:["chù","rán","wéi","jiè"],meaning:"警惕谨慎，提高戒备。怵然：警惕、小心翼翼的样子。"},{term:"视为止",pinyin:["shì","wéi","zhǐ"],meaning:"目光凝聚专注，停在那个难处上。"},{term:"謋然已解",pinyin:["huò","rán","yǐ","jiě"],meaning:"哗的一声，牛体已经分解开来。謋然：象声词，骨肉分离的声音。"},{term:"如土委地",pinyin:["rú","tǔ","wěi","dì"],meaning:"像泥土一样散落在地上。委：散落、堆积。"},{term:"踌躇满志",pinyin:["chóu","chú","mǎn","zhì"],meaning:"从容自得、心满意足的样子。成语出处即在此。"},{term:"善刀而藏之",pinyin:["shàn","dāo","ér","cáng","zhī"],meaning:"擦拭好刀，收藏起来。善：擦拭、保养。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"技进乎道，游刃有余",subtitle:"庄子用音乐和舞蹈来描写解牛——当技艺达到「道」的层面，劳动本身就变成了艺术。",lines:[{text:"手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不中音。合于《桑林》之舞，乃中《经首》之会。",tone:"合道",guide:"庄子用音乐和舞蹈来描写解牛——这不是在写一个厨师工作，而是在写一场人与自然完全合一的表演。手、肩、足、膝，每一个动作都有声音，每一个声音都合乎节拍。当技艺达到「道」的层面，劳动本身就变成了艺术。文惠君看到的是「技」，庄子要说的是「道」。"},{text:"臣之所好者，道也，进乎技矣。",tone:"由技入道",guide:"庖丁的第一句自述，直接点破全段主旨：我追求的不是技艺，而是道——技艺只是道的载体。「进乎技」不是说超越技艺、不要技艺，而是说：技艺是入口，道是目的地。当你通过技艺抵达道，技艺就不再是你的边界。"},{text:"始臣之解牛之时，所见无非牛者。三年之后，未尝见全牛也。",tone:"认知",guide:"庖丁描述了三个认知阶段：初学——眼中全是整头牛，被整体形态困住；三年后——不再见全牛，眼中只有结构、缝隙、间隔；如今——以神遇不以目视，超越感官，心神直接感应。这三个阶段，是所有深度学习的共同路径：从「看见整体」到「看见结构」，再到「超越看见」。"},{text:"依乎天理，批大郤，导大窾，因其固然。",tone:"顺势",guide:"这四句是庖丁解牛的核心方法，也是「缘督以为经」的具体演示：依乎天理（顺着牛体本来的自然结构）、批大郤（从大的缝隙处入刀）、导大窾（引刀进入大的空腔）、因其固然（顺着它本来的样子）。没有一个字是「强行」、「硬切」、「克服」。庄子的「道」，永远是顺势，不是对抗。这不只是解牛的方法，是处世的方法，是养生的方法。"},{text:"以无厚入有间，恢恢乎其于游刃必有余地矣。",tone:"余地",guide:"全段最精华的一句，也是成语「游刃有余」的出处：刀刃无厚（极薄），骨节有间（有缝隙）。用「无」去进入「有」的缝隙——绰绰有余。这是道家最核心的智慧之一：不是用力量去克服阻力，而是找到那个「间」，用「无厚」去穿越它。老子说「天下莫柔弱于水，而攻坚强者莫之能胜」——庖丁的刀，就是那把「水」。"},{text:"每至于族，吾见其难为，怵然为戒，视为止，行为迟，动刀甚微，謋然已解，如土委地。",tone:"敬畏",guide:"这一段常被忽略，却是全段最真实的部分：庖丁遇到筋骨交错的难处，不是硬冲，而是停下来——目光凝聚，动作放慢，刀轻轻一动，哗然解开。「怵然为戒」——即便是得道的庖丁，遇到难处依然保持敬畏。逍遥不是无所畏惧，而是在敬畏中找到那条缝隙。"},{text:"提刀而立，为之四顾，为之踌躇满志，善刀而藏之。",tone:"收束",guide:"全段最美的收尾：解完牛，庖丁提刀而立，环顾四周，踌躇满志，然后擦刀收藏。这不是骄傲，是一种完成之后的从容与满足。「踌躇满志」在这里是褒义——不是得意忘形，而是与道合一之后的内在圆满。善刀而藏——用完，收好，不炫耀，不执着。"},{text:"善哉！吾闻庖丁之言，得养生焉。",tone:"点睛",guide:"文惠君的最后一句，是全段的点睛：他来看的是解牛，听到的却是养生之道。庖丁从未提过「养生」二字，但文惠君听懂了。这正是庄子的写法——不直说道理，让故事自己说话。养生的道理，就藏在那把十九年刀刃若新的刀里。"}]}),i[11]||(i[11]=n("h2",{id:"三、右师一足·泽雉十步",tabindex:"-1"},[e("三、右师一足·泽雉十步 "),n("a",{class:"header-anchor",href:"#三、右师一足·泽雉十步","aria-label":'Permalink to "三、右师一足·泽雉十步"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:l,glossary:h,"default-mode":"classic","aria-label":"养生主·右师泽雉 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"公文轩",pinyin:["gōng","wén","xuān"],meaning:"人名，见到右师而感到惊讶的人。"},{term:"右师",pinyin:["yòu","shī"],meaning:"官名，这里指担任右师之职却只有一只脚的人。"},{term:"恶乎介也",pinyin:["wū","hū","jiè","yě"],meaning:"为什么只有一只脚？恶乎：为何、怎么；介：单，指独脚。"},{term:"泽雉",pinyin:["zé","zhì"],meaning:"野鸡，生活在沼泽中的雉鸟。"},{term:"蕲",pinyin:["qí"],meaning:"祈求、希望。不蕲畜乎樊中：不希望被关在笼子里饲养。"},{term:"畜乎樊中",pinyin:["xù","hū","fán","zhōng"],meaning:"在笼子里被饲养。畜：饲养；樊：笼子、栅栏。"},{term:"神虽王",pinyin:["shén","suī","wàng"],meaning:"精神虽然旺盛。王通「旺」，旺盛。笼中食物充足，精神看似好，但不自然。"},{term:"不善也",pinyin:["bù","shàn","yě"],meaning:"却不是好事。笼中虽饱，失去自由，精神之旺不是真正的好。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"分清天命与人为，自由胜于安逸",subtitle:"右师分清了「天」与「人」；泽雉用行动表明：自由比安逸更重要。",lines:[{text:"天也，非人也。天之生是使独也，人之貌有与也。以是知其天也，非人也。",tone:"天与人",guide:"这段对话的核心，是区分「天」与「人」：天（自然而然，命中注定）与人（人为施加，外力造成）。右师只有一只脚——公文轩第一反应是「刑罚所致」（人为），但答案是天生如此。庄子在这里埋下养生主最重要的一个命题：分清什么是天命，什么是人为——对天命坦然接受，不强求改变；对人为之事，不让它损耗生命。右师没有因为一只脚而怨天尤人，因为他知道：这是天，不是人的过错，也不是他的过错。"},{text:"泽雉十步一啄，百步一饮，不蕲畜乎樊中。神虽王，不善也。",tone:"自由",guide:"这是全篇最简洁、最有力的对比：泽中野鸡觅食艰辛（十步一啄，百步一饮）却自由真实；笼中之鸡食物充足、神虽旺，却不善。野鸡宁可艰辛觅食，也不愿被关进笼子。笼中精神再旺盛，也是「不善」——因为那不是真实的生命状态。这与逍遥游的「泽雉」精神一脉相承：自由比安逸更重要，真实比舒适更重要。养生，不是把自己关进一个「安全的笼子」，而是在真实的处境中，顺天而活。"}]}),i[15]||(i[15]=n("h2",{id:"四、老聃之死·秦失吊唁",tabindex:"-1"},[e("四、老聃之死·秦失吊唁 "),n("a",{class:"header-anchor",href:"#四、老聃之死·秦失吊唁","aria-label":'Permalink to "四、老聃之死·秦失吊唁"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),t(a,{sections:u,glossary:p,"default-mode":"classic","aria-label":"养生主·老聃之死 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),t(s,{items:[{term:"老聃",pinyin:["lǎo","dān"],meaning:"老子，道家创始人，姓李名耳，字聃。"},{term:"秦失",pinyin:["qín","yì"],meaning:"老子的朋友，得道之人。失通「佚」，人名。"},{term:"吊",pinyin:["diào"],meaning:"吊唁，前往悼念死者。"},{term:"三号而出",pinyin:["sān","háo","ér","chū"],meaning:"哭了三声就出来了。号：放声大哭。"},{term:"不蕲言而言",pinyin:["bù","qí","yán","ér","yán"],meaning:"不该说话却忍不住说。蕲：祈求、希望，这里引申为「应该」。"},{term:"不蕲哭而哭",pinyin:["bù","qí","kū","ér","kū"],meaning:"不该哭泣却忍不住哭。情绪失控，超出了自然的悲伤。"},{term:"遁天倍情",pinyin:["dùn","tiān","bèi","qíng"],meaning:"逃避天命、违背真情。遁：逃避；倍通「背」，违背；情：真实的情感。"},{term:"忘其所受",pinyin:["wàng","qí","suǒ","shòu"],meaning:"忘记了自己从天地所受的本性。所受：天赋的本性与命运。"},{term:"遁天之刑",pinyin:["dùn","tiān","zhī","xíng"],meaning:"逃避天命所受的惩罚。不顺天命，反而自我折磨，是一种刑罚。"},{term:"安时而处顺",pinyin:["ān","shí","ér","chǔ","shùn"],meaning:"安于时机，顺应自然。安时：安然接受时势；处顺：处于顺应自然的状态。"},{term:"帝之县解",pinyin:["dì","zhī","xuán","jiě"],meaning:"上天赐予的解脱。帝：天帝，自然；县通「悬」，悬挂；解：解脱、解开。如同被悬挂的倒置之人得到解脱。"},{term:"指穷于为薪",pinyin:["zhǐ","qióng","yú","wéi","xīn"],meaning:"手指（劈柴的动作）在薪柴烧尽时停止。指：手指，引申为劈柴的动作；穷：穷尽、终止；薪：柴火。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),t(r,{title:"适来是时，适去是顺",subtitle:"生死都是「顺」——安时而处顺，哀乐不能入。",lines:[{text:"三号而出。",tone:"反常",guide:"秦失只哭了三声就出来了——这是全段的引子，也是庄子故意设置的「反常」：好友去世，只哭三声，旁人当然觉得奇怪。但庄子要说的是：那些哭得撕心裂肺的人，才是真正的「不对」。三声，是真实的悲伤；嚎啕不止，是表演，是执着，是「遁天倍情」。"},{text:"有老者哭之，如哭其子；少者哭之，如哭其母。",tone:"照见",guide:"秦失观察到的场景：老人哭老子，像哭自己的孩子；年轻人哭老子，像哭自己的母亲。哭的不是老子，是自己的执着与依赖。这种哭，已经超出了对死者的悼念，变成了对「失去」本身的恐惧与抗拒。庄子不是说不能悲伤，而是说：悲伤要真实，不要变成自我折磨。"},{text:"是遁天倍情，忘其所受，古者谓之遁天之刑。",tone:"遁天",guide:"三个递进的判断：遁天（逃避天命——死亡是天命，抗拒它是逃避）；倍情（违背真情——真实的悲伤是有限度的，无限放大是违背真情）；忘其所受（忘记了自己从天地所受的本性）。「遁天之刑」——逃避天命，反而给自己套上了枷锁，这本身就是一种惩罚。不是外人惩罚你，是你自己惩罚自己。"},{text:"适来，夫子时也；适去，夫子顺也。安时而处顺，哀乐不能入也。",tone:"安时",guide:"这是庄子对生死最平静、最有力的表述：来，顺应了时机（时）；去，顺应了自然（顺）。生与死，都是「顺」——没有一个是错的，没有一个需要抗拒。「安时而处顺」——安于当下的时机，处于顺应自然的状态——这时候，哀乐都进不来，不是因为没有感情，而是因为内心已经与天地的节律合一，悲喜不再是外来的冲击。"},{text:"古者谓之帝之县解。",tone:"解脱",guide:"「帝之县解」——上天赐予的解脱。县（悬）：像一个被倒悬的人，痛苦至极；解：解开那根绳子。死亡，不是终结，而是解脱。那些嚎啕大哭的人，是在把死者重新「悬」起来——用自己的执着，不让死者得到那个解脱。"},{text:"指穷于为薪，火传也，不知其尽也。",tone:"薪火",guide:"全篇最后一句，也是《庄子》内篇里最神秘、最开放的一句收尾。薪柴（有形的载体）会燃尽，火（无形的传续）不知其尽。这个比喻可以有很多层读法：身体是薪，生命之火传续——形态消逝，道不灭；老子是薪，他的思想是火——人会死，道不死；每一个「我」是薪，天地的生命力是火——小我消逝，大我永续。庄子没有说「火是什么」，没有说「传到哪里去」——「不知其尽」，是庄子留给我们的最后一个开放的问题。养生，不是让薪柴烧得更久，而是让火传得更远。"}]}),i[19]||(i[19]=c("",37))])}}});export{f as __pageData,P as default};
